mapper.insert:
insert into sys_git_webhook_delivery (
    webhook_id, repository_id, event, delivery_guid, request_headers_summary, request_body,
    response_status, response_body_truncated, duration_ms, success, error_message, create_time
) values (
    #{webhookId}, #{repositoryId}, #{event}, #{deliveryGuid}, #{requestHeadersSummary}, #{requestBody},
    #{responseStatus}, #{responseBodyTruncated}, #{durationMs}, #{success}, #{errorMessage}, #{createTime}
)

mapper.delete:
delete from sys_git_webhook_delivery
where webhook_id = #{webhookId}
  and delivery_id not in (
    select delivery_id from (
        select delivery_id
        from sys_git_webhook_delivery
        where webhook_id = #{webhookId}
        order by create_time desc, delivery_id desc
        limit #{keepCount}
    ) keep_rows
  )
